    Expression<int>? id,
    Expression<String>? sku,
    Expression<String>? barcode,
    Expression<String>? name,
    Expression<String>? nameAr,
    Expression<String>? nameFr,
    Expression<String>? description,
    Expression<int>? categoryId,
