class Employee extends DataClass implements Insertable<Employee> {
  final int id;

  /// Unique employee code (e.g., EMP001)
  final String? employeeCode;

  /// Link to users table for system access
  final int? userId;
  final String name;
  final String? nameAr;
  final String? nameFr;
  final String? email;
  final String? phone;
  final String? position;
  final String? department;

  /// Role for permissions
  final int? roleId;

  /// Manager (self-referencing for hierarchy)
  final int? managerId;
  final Decimal? salaryCents;

  /// Default commission rate in basis points (e.g., 500 = 5%)
  final int defaultCommissionRateBps;

  /// Fixed commission amount in cents (used when commission type is 'fixed')
  final Decimal? fixedCommissionCents;

  /// Commission type: 'percentage' or 'fixed'
  final String commissionType;

  /// Monthly sales target in cents
  final Decimal? salesTargetCents;

  /// Bonus amount in cents when sales target is achieved
  final Decimal? targetBonusCents;

  /// Target period: monthly, quarterly, yearly
  final String targetPeriod;

  /// Pay period type: monthly, weekly, daily
  final String payPeriodType;

  /// Working days per pay period (e.g., 26 for monthly)
  final int workingDaysPerPeriod;

  /// Working hours per day (e.g., 8)
  final int workingHoursPerDay;

  /// Absence deduction rate in basis points (10000 = 100% of daily rate)
  final int absenceDeductionRateBps;

  /// Late deduction rate in basis points (2500 = 25% of daily rate)
  final int lateDeductionRateBps;

  /// Overtime calculation type: 'hourly_rate' (based on hourly salary), 'percentage' (% of daily rate), 'fixed' (fixed amount per hour)
  final String overtimeCalcType;

  /// Overtime rate in basis points (15000 = 150% of hourly rate for 'hourly_rate'/'percentage', or fixed cents for 'fixed')
  final int overtimeRateBps;
  final int currencyId;
  final bool isActive;
  final DateTime? hireDate;
  final DateTime? terminationDate;

  /// JSON array of weekly off-day numbers (1=Mon..7=Sun), e.g. "[5,6]" for Fri+Sat
  final String weeklyOffDays;

  /// Annual leave allowance in days
  final int annualLeaveDays;
  final String? notes;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Employee({
