class $$CurrenciesTableTableManager
    extends
        RootTableManager<
          _$AppDatabase,
          $CurrenciesTable,
          Currency,
          $$CurrenciesTableFilterComposer,
          $$CurrenciesTableOrderingComposer,
          $$CurrenciesTableAnnotationComposer,
          $$CurrenciesTableCreateCompanionBuilder,
          $$CurrenciesTableUpdateCompanionBuilder,
          (Currency, $$CurrenciesTableReferences),
          Currency,
          PrefetchHooks Function({
            bool suppliersRefs,
            bool productsRefs,
            bool customersRefs,
            bool customerTransactionsRefs,
            bool supplierTransactionsRefs,
            bool employeesRefs,
            bool salesRefs,
            bool commissionsRefs,
            bool payrollsRefs,
            bool saleReturnsRefs,
            bool salePaymentsRefs,
            bool purchasesRefs,
            bool purchaseReturnsRefs,
            bool purchasePaymentsRefs,
            bool accountsRefs,
            bool journalEntryLinesRefs,
            bool expensesRefs,
          })
        > {
  $$CurrenciesTableTableManager(_$AppDatabase db, $CurrenciesTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$CurrenciesTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$CurrenciesTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$CurrenciesTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                Value<String> code = const Value.absent(),
                Value<String> name = const Value.absent(),
                Value<String> symbol = const Value.absent(),
                Value<Decimal> exchangeRate = const Value.absent(),
                Value<bool> isBase = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
              }) => CurrenciesCompanion(
                id: id,
                code: code,
                name: name,
                symbol: symbol,
                exchangeRate: exchangeRate,
                isBase: isBase,
                isActive: isActive,
                createdAt: createdAt,
                updatedAt: updatedAt,
              ),
          createCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                required String code,
                required String name,
                required String symbol,
                required Decimal exchangeRate,
                Value<bool> isBase = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
              }) => CurrenciesCompanion.insert(
                id: id,
                code: code,
                name: name,
                symbol: symbol,
                exchangeRate: exchangeRate,
                isBase: isBase,
                isActive: isActive,
                createdAt: createdAt,
                updatedAt: updatedAt,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable(table),
                  $$CurrenciesTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                suppliersRefs = false,
                productsRefs = false,
                customersRefs = false,
                customerTransactionsRefs = false,
                supplierTransactionsRefs = false,
                employeesRefs = false,
                salesRefs = false,
                commissionsRefs = false,
                payrollsRefs = false,
                saleReturnsRefs = false,
                salePaymentsRefs = false,
                purchasesRefs = false,
                purchaseReturnsRefs = false,
                purchasePaymentsRefs = false,
                accountsRefs = false,
                journalEntryLinesRefs = false,
                expensesRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
